args.query:
\dt api.*
\dv api.*
select table_schema,table_name,column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema in ('api','public') order by 1,2,ordinal_position;
select * from api.app_user;
select tgname, tgrelid::regclass, pg_get_triggerdef(oid) from pg_trigger where not tgisinternal;
select schemaname,tablename,policyname,cmd,roles,qual,with_check from pg_policies;
select proname,pronamespace::regnamespace,prosecdef from pg_proc where pronamespace::regnamespace::text in ('api','public');

select * from api.company; select * from api.status order by ord;
select p.proname, pg_get_functiondef(p.oid) from pg_proc p where pronamespace::regnamespace::text='private';
select grantee,table_name,privilege_type,column_name from information_schema.column_privileges where table_schema='api' and grantee in ('applicant','expert','fund_admin','anon','authenticator') order by 2,1,4;
select grantee,table_name,privilege_type from information_schema.table_privileges where table_schema='api' and grantee in ('applicant','expert','fund_admin','anon','authenticator','PUBLIC');
select conname,conrelid::regclass,pg_get_constraintdef(oid) from pg_constraint where connamespace='api'::regnamespace;
select relname,relrowsecurity,relforcerowsecurity from pg_class where relnamespace='api'::regnamespace and relkind='r';

insert into api.company(id,name,inn,funding_limit) values (20014,'ООО «Дельта»','7700004036',4000000);
insert into api.app_user(login,fio,role,company_id) values ('delta_user','Дельтов Олег','applicant',20014);
insert into api.application(number,company_id,amount,description) values ('TEST-D1',20014,100,'t'),('TEST-A1',20005,100,'t') returning id;

